#!/bin/bash
# Release build: same cmake options as experiments/pg-split-virtual/scripts/05_build.sh.
set -e
W=/home/dev_path/ceph-udvss-release; LOG=/home/dev_path/udvss-release-logs
CPUS=$(python3 -c "print(','.join(str(c) for c in range(48) if c not in (8,11,14,17,20)))")
mkdir -p $W/build && cd $W/build
[ -f CMakeCache.txt ] || cmake -DBOOST_J=48 -DCMAKE_BUILD_TYPE=RelWithDebInfo -DCMAKE_CXX_COMPILER=/usr/bin/g++-13 -DCMAKE_C_COMPILER=/usr/bin/gcc-13 -DENABLE_GIT_VERSION=OFF -DSeastar_DPDK=OFF -DWITH_ASAN=OFF -DWITH_ASAN_LEAK=OFF -DWITH_BABELTRACE=OFF -DWITH_BLKIN=OFF -DWITH_BLUEFS=OFF -DWITH_BLUESTORE=ON -DWITH_BLUESTORE_PMEM=OFF -DWITH_BOOST_VALGRIND=OFF -DWITH_BREAKPAD=OFF -DWITH_BROTLI=OFF -DWITH_CATCH2=OFF -DWITH_CCACHE=OFF -DWITH_CEPHADM=ON -DWITH_CEPHFS=OFF -DWITH_CEPHFS_JAVA=OFF -DWITH_CPUTRACE=OFF -DWITH_CRIMSON=ON -DWITH_DMCLOCK_TESTS=OFF -DWITH_DOKAN=OFF -DWITH_DPDK=OFF -DWITH_EC_ISA_PLUGIN=TRUE -DWITH_FIO=OFF -DWITH_FMT_HEADER_ONLY=OFF -DWITH_FUSE=OFF -DWITH_GRAFANA=OFF -DWITH_GSSAPI=OFF -DWITH_GTEST_PARALLEL=OFF -DWITH_JAEGER=OFF -DWITH_KRBD=OFF -DWITH_KVS=OFF -DWITH_LIBCEPHFS=OFF -DWITH_LIBCEPHSQLITE=OFF -DWITH_LIBRADOSSTRIPER=OFF -DWITH_LIBURING=ON -DWITH_LTTNG=OFF -DWITH_LZ4=ON -DWITH_MANPAGE=OFF -DWITH_MGR=ON -DWITH_MGR_DASHBOARD_FRONTEND=OFF -DWITH_MGR_ROOK_CLIENT=ON -DWITH_NVMEOF_GATEWAY_MONITOR_CLIENT=OFF -DWITH_OCF=OFF -DWITH_OPENLDAP=OFF -DWITH_OPENSSL_ENGINE=OFF -DWITH_OSD_INSTRUMENT_FUNCTIONS=OFF -DWITH_PROFILER=OFF -DWITH_PYPKG=OFF -DWITH_PYTHON3=3 -DWITH_QATDRV=OFF -DWITH_QATLIB=ON -DWITH_QATZIP=ON -DWITH_RADOSGW=OFF -DWITH_RADOSGW_AMQP_ENDPOINT=OFF -DWITH_RADOSGW_ARROW_FLIGHT=OFF -DWITH_RADOSGW_BACKTRACE_LOGGING=OFF -DWITH_RADOSGW_BEAST_OPENSSL=ON -DWITH_RADOSGW_D4N=ON -DWITH_RADOSGW_DAOS=OFF -DWITH_RADOSGW_DBSTORE=ON -DWITH_RADOSGW_KAFKA_ENDPOINT=ON -DWITH_RADOSGW_LUA_PACKAGES=ON -DWITH_RADOSGW_MOTR=OFF -DWITH_RADOSGW_POSIX=ON -DWITH_RADOSGW_RADOS=ON -DWITH_RADOSGW_SELECT_PARQUET=ON -DWITH_RBD=OFF -DWITH_RDMA=ON -DWITH_REENTRANT_STRSIGNAL=OFF -DWITH_SCCACHE=OFF -DWITH_SELINUX=OFF -DWITH_SPDK=OFF -DWITH_STATIC_LIBSTDCXX=OFF -DWITH_SYSTEMD=OFF -DWITH_SYSTEM_ARROW=OFF -DWITH_SYSTEM_BOOST=OFF -DWITH_SYSTEM_CATCH2=OFF -DWITH_SYSTEM_FMT=OFF -DWITH_SYSTEM_GTEST=OFF -DWITH_SYSTEM_JERASURE=OFF -DWITH_SYSTEM_LIBURING=OFF -DWITH_SYSTEM_NPM=OFF -DWITH_SYSTEM_QATLIB=OFF -DWITH_SYSTEM_QATZIP=OFF -DWITH_SYSTEM_ROCKSDB=OFF -DWITH_SYSTEM_UTF8PROC=OFF -DWITH_SYSTEM_ZSTD=OFF -DWITH_TESTS=ON -DWITH_THREAD_SAFE_RES_QUERY=OFF -DWITH_TSAN=OFF -DWITH_UBSAN=OFF -DWITH_XFS=ON -DWITH_ZNS=OFF .. > $LOG/cmake.log 2>&1
echo "[$(date -u +%FT%TZ)] cmake done"
taskset -c $CPUS nice -n 10 make -j40 -k vstart-base crimson-osd ceph-vector-bench-native \
  unittest_vector_pg_lsh_boundary unittest_vector_pg_lsh_hierarchical unittest_vector_pg_lsh_query_routing \
  unittest_vector_query_exec unittest_vector_query_exec_int8_simd unittest_vector_selective_fanout \
  unittest-transaction-manager unittest-fltree-onode-manager unittest-seastore ceph_test_rados_api_io_pp \
  > $LOG/make.log 2>&1
echo "[$(date -u +%FT%TZ)] BUILD_OK"
